<?php
require_once 'sacco_common.php';
$loanId=(int)($_GET['id']??0);if($loanId<1)die('Invalid loan.');
$q=$conn->prepare("SELECT l.*,m.sacco_account_no,s.sacco_name,COALESCE(NULLIF(TRIM(CONCAT(e.first_name,' ',e.last_name)),''),u.email,CONCAT('User #',u.user_id)) full_name,COALESCE(SUM(r.amount),0) total_repaid FROM hr_sacco_loans l JOIN hr_sacco_members m ON m.sacco_member_id=l.sacco_member_id JOIN hr_saccos s ON s.sacco_id=m.sacco_id JOIN users u ON u.user_id=m.user_id LEFT JOIN employees e ON e.employee_id=u.employee_id LEFT JOIN hr_sacco_loan_repayments r ON r.loan_id=l.loan_id WHERE l.loan_id=? GROUP BY l.loan_id,m.sacco_account_no,s.sacco_name,full_name");$q->bind_param('i',$loanId);$q->execute();$loan=$q->get_result()->fetch_assoc();$q->close();if(!$loan)die('Loan not found.');
$q=$conn->prepare("SELECT * FROM hr_sacco_loan_repayments WHERE loan_id=? ORDER BY repayment_date,repayment_id");$q->bind_param('i',$loanId);$q->execute();$rows=$q->get_result();$balance=$loan['principal_amount']+$loan['interest_amount']-$loan['total_repaid'];
require_once 'navbar.php';
?><main class="ml-64 p-6 max-w-5xl mx-auto"><div class="flex justify-between items-center mb-5 print:hidden"><h1 class="text-2xl font-bold">SACCO Loan Statement</h1><button onclick="window.print()" class="bg-blue-600 text-white px-4 py-2 rounded">Print</button></div><section class="bg-white border rounded-xl p-6"><h2 class="text-xl font-bold mb-1"><?=se($loan['full_name'])?></h2><p class="text-gray-500"><?=se($loan['sacco_name'])?> · <?=se($loan['sacco_account_no'])?></p><div class="grid md:grid-cols-4 gap-3 my-6"><div class="bg-gray-50 p-3 rounded"><small>Loan Principal</small><b class="block">KSh <?=sm($loan['principal_amount'])?></b></div><div class="bg-gray-50 p-3 rounded"><small>Interest</small><b class="block">KSh <?=sm($loan['interest_amount'])?></b></div><div class="bg-gray-50 p-3 rounded"><small>Total Repaid</small><b class="block">KSh <?=sm($loan['total_repaid'])?></b></div><div class="bg-blue-50 p-3 rounded"><small>Outstanding</small><b class="block">KSh <?=sm(max(0,$balance))?></b></div></div><p class="text-sm mb-4">Loan reference: <?=se($loan['loan_reference']?:'Loan #'.$loan['loan_id'])?> · Issued: <?=se($loan['issue_date'])?> · Due: <?=se($loan['due_date']?:'Not specified')?></p><h3 class="font-bold mb-2">Repayment History</h3><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">Date</th><th class="p-3 text-right">Amount</th><th class="p-3">Method</th><th class="p-3">Reference</th><th class="p-3 text-left">Notes</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr class="border-t"><td class="p-3"><?=se($r['repayment_date'])?></td><td class="p-3 text-right">KSh <?=sm($r['amount'])?></td><td class="p-3 text-center"><?=se($r['payment_method'])?></td><td class="p-3 text-center"><?=se($r['reference_number'])?></td><td class="p-3"><?=se($r['notes'])?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="p-5 text-center text-gray-500">No repayments recorded.</td></tr><?php endif;?></tbody></table></div></section></main><style>@media print{.ml-64{margin-left:0!important}.print\:hidden{display:none!important}body{background:white}}</style>
